import { isAsciiLetterOrDigit, lowerAscii } from './html.mjs';

export function createSlugger() {
  const seen = new Map();

  return {
    next(text) {
      const base = slugify(text);

      if (base === '') {
        const count = (seen.get('') || 0) + 1;
        seen.set('', count);
        return `_${count}`;
      }

      const used = seen.get(base) || 0;
      seen.set(base, used + 1);

      if (used === 0) {
        return base;
      }

      return `${base}_${used}`;
    },
  };
}

export function slugify(text) {
  let result = '';
  let pendingDash = false;

  for (let i = 0; i < text.length; i += 1) {
    const lower = lowerAscii(text[i]);

    if (isAsciiLetterOrDigit(lower)) {
      if (pendingDash && result.length > 0) {
        result += '-';
      }

      result += lower;
      pendingDash = false;
      continue;
    }

    if (lower === '-' || lower === ' ' || lower === '\t') {
      pendingDash = true;
    }
  }

  if (pendingDash && result.length > 0) {
    result += '-';
  }

  return result;
}

