export function renderToc(headings) {
  const tree = buildHeadingTree(headings);
  return `<div class="toc">\n${renderHeadingList(tree)}</div>`;
}

function buildHeadingTree(headings) {
  const root = { level: 0, children: [] };
  const stack = [root];

  for (let i = 0; i < headings.length; i += 1) {
    const heading = headings[i];
    const node = {
      id: heading.id,
      level: heading.level,
      text: heading.text,
      children: [],
    };

    while (
      stack.length > 1 &&
      stack[stack.length - 1].level >= heading.level
    ) {
      stack.pop();
    }

    stack[stack.length - 1].children.push(node);
    stack.push(node);
  }

  return root.children;
}

function renderHeadingList(nodes) {
  let html = '<ul>\n';

  for (let i = 0; i < nodes.length; i += 1) {
    const node = nodes[i];

    html += `<li><a href="#${escapeHtmlAttribute(node.id)}">${node.text}</a>`;

    if (node.children.length > 0) {
      html += renderHeadingList(node.children);
      html += '</li>\n';
    } else {
      html += '</li>\n';
    }
  }

  html += '</ul>\n';
  return html;
}

