export function parseArguments(argv, programName) {
  const values = {
    a: undefined,
    b: undefined,
    c: undefined,
  };
  const unrecognized = [];
  let index = 0;

  while (index < argv.length) {
    const token = argv[index];

    if (token === '-h' || token === '--help') {
      return {
        help: true,
      };
    }

    if (token === '--') {
      for (let i = index + 1; i < argv.length; i += 1) {
        unrecognized.push(argv[i]);
      }

      break;
    }

    if (token.startsWith('--')) {
      const equalsIndex = token.indexOf('=');
      let name = token;
      let value = null;

      if (equalsIndex !== -1) {
        name = token.slice(0, equalsIndex);
        value = token.slice(equalsIndex + 1);
      }

      if (name === '--a' || name === '--b' || name === '--c') {
        if (value === null) {
          if (
            index + 1 >= argv.length ||
            (argv[index + 1].startsWith('-') && argv[index + 1] !== '-')
          ) {
            return {
              error: `argument ${name}: expected one argument`,
            };
          }

          value = argv[index + 1];
          index += 1;
        }

        values[name.slice(2)] = value;
        index += 1;
        continue;
      }

      unrecognized.push(token);

      if (
        equalsIndex === -1 &&
        index + 1 < argv.length &&
        (!argv[index + 1].startsWith('-') || argv[index + 1] === '-')
      ) {
        unrecognized.push(argv[index + 1]);
        index += 1;
      }

      index += 1;
      continue;
    }

    unrecognized.push(token);
    index += 1;
  }

  const missing = [];

  if (values.a === undefined) {
    missing.push('--a');
  }

  if (values.b === undefined) {
    missing.push('--b');
  }

  if (values.c === undefined) {
    missing.push('--c');
  }

  if (missing.length > 0) {
    return {
      error: `the following arguments are required: ${missing.join(', ')}`,
    };
  }

  if (unrecognized.length > 0) {
    return {
      error: `unrecognized arguments: ${unrecognized.join(' ')}`,
    };
  }

  return {
    help: false,
    values,
  };
}

export function formatHelp(programName) {
  return (
    `usage: ${programName} [-h] --a A --b B --c C\n\n` +
    'Markdown with extension configuration\n\n' +
    'options:\n' +
    '  -h, --help  show this help message and exit\n' +
    '  --a A\n' +
    '  --b B\n' +
    '  --c C\n'
  );
}

export function formatError(programName, message) {
  return (
    `usage: ${programName} [-h] --a A --b B --c C\n` +
    `${programName}: error: ${message}\n`
  );
}

export function basename(path) {
  if (!path || path.length === 0) {
    return 'test13.mjs';
  }

  let slash = path.lastIndexOf('/');
  const backslash = path.lastIndexOf('\\');

  if (backslash > slash) {
    slash = backslash;
  }

  if (slash === -1) {
    return path;
  }

  return path.slice(slash + 1);
}

