export function renderInline(source) {
  return parseInlineRange(source, 0, source.length);
}

function parseInlineRange(source, start, end) {
  let html = '';
  let text = '';
  let index = start;

  while (index < end) {
    const entity = tryParseEntity(source, index, end);

    if (entity !== null) {
      html += entity.html;
      text += entity.text;
      index = entity.end;
      continue;
    }

    const codeSpan = tryParseCodeSpan(source, index, end);

    if (codeSpan !== null) {
      html += codeSpan.html;
      text += codeSpan.text;
      index = codeSpan.end;
      continue;
    }

    const link = tryParseLink(source, index, end);

    if (link !== null) {
      html += link.html;
      text += link.text;
      index = link.end;
      continue;
    }

    const emphasis = tryParseEmphasis(source, index, end);

    if (emphasis !== null) {
      html += emphasis.html;
      text += emphasis.text;
      index = emphasis.end;
      continue;
    }

    const tag = tryParseRawTag(source, index, end);

    if (tag !== null) {
      html += tag.html;
      index = tag.end;
      continue;
