    return '<';
  }

  if (entity === '&gt;') {
    return '>';
  }

  if (entity === '&quot;') {
    return '"';
  }

  if (entity === '&#39;') {
    return "'";
  }

  if (entity === '&nbsp;') {
    return ' ';
