  }

  const urlStart = cursor + 2;
  let urlCursor = urlStart;
  let urlDepth = 1;

  while (urlCursor < end) {
    const ch = source[urlCursor];

    if (ch === '(') {
      urlDepth += 1;
    } else if (ch === ')') {
      urlDepth -= 1;

      if (urlDepth === 0) {
        break;
      }
    }

