import {
  countLeadingSpaces,
  escapeHtmlAttribute,
  escapeHtmlText,
  lowerAscii,
  splitLines,
  stripOneIndent,
  trimAsciiWhitespace,
} from './html.mjs';
import { renderInline } from './inline.mjs';
import { createSlugger } from './slug.mjs';
import { renderToc } from './toc.mjs';

const BLOCK_TAGS = new Set([
  'address',
  'article',
  'aside',
  'blockquote',
  'details',
  'div',
  'dl',
  'fieldset',
  'figcaption',
  'figure',
  'footer',
  'form',
  'h1',
  'h2',
  'h3',
  'h4',
  'h5',
  'h6',
  'header',
  'hr',
  'main',
  'nav',
  'ol',
  'p',
  'pre',
  'section',
  'table',
  'tbody',
  'td',
  'tfoot',
  'th',
  'thead',
  'tr',
  'ul',
]);

export function renderMarkdown(source, options = {}) {
  const lines = splitLines(source);
  const state = {
    headings: [],
    slugger: createSlugger(),
  };
  const blocks = [];
  let index = 0;

  while (index < lines.length) {
    const line = lines[index];

    if (line.length === 0) {
      index += 1;
      continue;
    }

    if (options.toc && trimAsciiWhitespace(line) === '[TOC]') {
      blocks.push({ type: 'toc' });
      index += 1;
      continue;
    }

    if (options.tables) {
      const table = tryParseTable(lines, index);

      if (table !== null) {
        blocks.push({ type: 'html', html: table.html });
        index = table.nextIndex;
        continue;
      }
    }

    if (options.fencedCode) {
      const fenced = tryParseFencedCode(lines, index);

      if (fenced !== null) {
        blocks.push({ type: 'html', html: fenced.html });
        index = fenced.nextIndex;
        continue;
      }
    }

    const htmlBlock = tryParseHtmlBlock(lines, index);

    if (htmlBlock !== null) {
      blocks.push({ type: 'html', html: htmlBlock.html });
      index = htmlBlock.nextIndex;
      continue;
    }

    const setextHeading = tryParseSetextHeading(lines, index, options, state);

    if (setextHeading !== null) {
      blocks.push({ type: 'html', html: setextHeading.html });
      index = setextHeading.nextIndex;
      continue;
    }

    const atxHeading = tryParseAtxHeading(line, options, state);

    if (atxHeading !== null) {
      blocks.push({ type: 'html', html: atxHeading.html });
      index += 1;
      continue;
    }

    if (isHorizontalRule(line)) {
      blocks.push({ type: 'html', html: '<hr />' });
      index += 1;
      continue;
    }

    const indentedCode = tryParseIndentedCode(lines, index, options);

    if (indentedCode !== null) {
      blocks.push({ type: 'html', html: indentedCode.html });
      index = indentedCode.nextIndex;
      continue;
    }

    const list = tryParseList(lines, index);

    if (list !== null) {
      blocks.push({ type: 'html', html: list.html });
      index = list.nextIndex;
      continue;
    }

    const paragraph = parseParagraph(lines, index, options);
    blocks.push({ type: 'html', html: `<p>${renderInline(paragraph.text).html}</p>` });
    index = paragraph.nextIndex;
  }

  if (options.toc) {
    const tocHtml = renderToc(state.headings);

    for (let i = 0; i < blocks.length; i += 1) {
      if (blocks[i].type === 'toc') {
        blocks[i] = { type: 'html', html: tocHtml };
      }
    }
  }

  return joinBlocks(blocks);
}

function joinBlocks(blocks) {
  let html = '';

  for (let i = 0; i < blocks.length; i += 1) {
    if (i > 0) {
      html += '\n';
    }

    html += blocks[i].html;
  }

  return html;
}

function tryParseAtxHeading(line, options, state) {
  let cursor = 0;

  while (cursor < line.length && line[cursor] === ' ' && cursor < 3) {
    cursor += 1;
