  if (token.length === 1) {
    return false;
  }
  const next = token[1];
  return next !== ' ' && next !== '\t' && next !== '\n';
}

function readSeparateValue(argv, index, optionName, programName) {
  const nextIndex = index + 1;
  if (nextIndex >= argv.length) {
    return {
      kind: 'error',
      errorText: formatError(programName, `argument ${optionName}: expected one argument`),
    };
  }

  const value = argv[nextIndex];
  if (isMissingValueToken(value)) {
    return {
      kind: 'error',
      errorText: formatError(programName, `argument ${optionName}: expected one argument`),
    };
  }

  return {
    kind: 'value',
    value,
    nextIndex: nextIndex + 1,
  };
}

function missingRequired(values) {
  const missing = [];
  for (let i = 0; i < REQUIRED_OPTIONS.length; i += 1) {
    const key = REQUIRED_OPTIONS[i];
    if (values[key] === undefined) {
      missing.push(`--${key}`);
    }
  }
  return missing;
}

export function parseArguments(argv = process.argv) {
  const programName = getProgramName(argv);
  const values = {
    a: undefined,
    b: undefined,
    c: undefined,
  };
  const extras = [];

  let index = 2;
  while (index < argv.length) {
    const token = argv[index];

    if (token === '-h' || token === '--help') {
      return {
        kind: 'help',
        helpText: formatHelp(programName),
      };
    }

    if (token === '--') {
      for (let extraIndex = index + 1; extraIndex < argv.length; extraIndex += 1) {
        extras.push(argv[extraIndex]);
      }
      break;
    }

    const inlineValue = splitInlineValue(token);
    if (inlineValue !== null && isKnownOptionName(inlineValue.name)) {
      values[inlineValue.name.slice(2)] = inlineValue.value;
      index += 1;
      continue;
    }

    if (isKnownOptionName(token)) {
      const parsedValue = readSeparateValue(argv, index, token, programName);
      if (parsedValue.kind === 'error') {
        return {
          kind: 'error',
          errorText: parsedValue.errorText,
          exitCode: 2,
        };
      }
      values[token.slice(2)] = parsedValue.value;
      index = parsedValue.nextIndex;
      continue;
    }

    extras.push(token);
    index += 1;
  }

  const missing = missingRequired(values);
  if (missing.length > 0) {
    return {
      kind: 'error',
      errorText: formatError(programName, `the following arguments are required: ${missing.join(', ')}`),
      exitCode: 2,
    };
  }

  if (extras.length > 0) {
    return {
      kind: 'error',
      errorText: formatError(programName, `unrecognized arguments: ${extras.join(' ')}`),
      exitCode: 2,
    };
  }

  return {
    kind: 'ok',
    values,
  };
}

